import json, re, os, sys
sp = os.path.dirname(os.path.abspath(__file__))
cat = 'C:/Users/edmem/OneDrive/Desktop/Minecraft Channel/studio/catalog'
batch = json.load(open(cat + '/tag_batches/review_speech_2.json', encoding='utf8'))
tax = json.load(open(cat + '/taxonomy.json', encoding='utf8'))
assets = batch['assets']

FOLD = {
 'R': 'Meme Videos/Reactions', 'C': 'Meme Videos/Clips & Templates', 'T': 'Meme Videos/Time Cards & Interludes',
 'V': 'Meme Videos/TV & Glitch', 'G': 'Green Screen/Characters & Memes', 'E': 'Green Screen/Effects & Explosions',
 'X': 'Green Screen/Text, Badges & Popups', 'I': 'Green Screen/Emojis & Icons',
 'N': 'Overlays & VFX/Glitch & VHS', 'S': 'Overlays & VFX/Speed Lines & Shapes'}
CAT = {'R': 'meme_video', 'C': 'meme_video', 'T': 'meme_video', 'V': 'meme_video', 'G': 'green_screen', 'E': 'green_screen',
       'X': 'green_screen', 'I': 'green_screen', 'N': 'overlay', 'S': 'overlay'}
ROLE = dict(c='cutaway', r='reaction', v='voice_line', o='overlay', s='stinger', t='transition', p='plate', l='laugh_track', m='motion_graphic', h='hit')
KEY = dict(n='none', g='green', b='black_screen', u='blue')
CR = dict(L='low', M='medium', H='high')

specs = {}
for fn in ('specs1.txt', 'specs2.txt'):
    for line in open(os.path.join(sp, fn), encoding='utf8'):
        line = line.strip()
        if not line:
            continue
        f = [x.strip() for x in line.split(' | ')]
        assert len(f) == 15, (len(f), line[:80])
        specs[int(f[0])] = f

def clean_from_path(path):
    stem = os.path.splitext(os.path.basename(path))[0]
    stem = re.sub(r'^\d+\.\s*', '', stem)
    stem = stem.replace('Ã±', 'n').replace('â€™', "'")
    stem = re.sub(r'(?<=[A-Za-z])_(?=[a-z])', "'", stem)
    stem = stem.replace('_', ' ').replace('  ', ' ').strip().rstrip('.').strip()
    return stem

out = []
for i, a in enumerate(assets):
    f = specs[i]
    _, org, rate, cr, key, fld, desc, moms, roles, tags, quote, win, en, mood, notes = f
    category = CAT[fld]
    k = KEY[key]
    if k == 'black_screen' and i != 73:
        k = 'none'
    dur = a['duration_s']
    if win == '-':
        uw = None
    elif win.startswith('='):
        s, e = win[1:].split('-')
        uw = [float(s), min(float(e), round(dur, 2))]
    else:
        s, e = win.split('-')
        uw = [round(max(0, float(s) - 0.15), 2), round(min(dur, float(e) + 0.3), 2)]
    if uw and uw[1] <= uw[0]:
        uw = [0, round(dur, 2)]
    if uw and uw[0] == 0 and abs(uw[1] - dur) < 0.2:
        uw = None if dur < 6 else uw
    if category == 'meme_video':
        placement = 'fullscreen'
    elif category == 'green_screen':
        placement = 'overlay_center'
    else:
        placement = 'overlay_any'
    q = None if quote == '-' else quote
    tg = [t.strip() for t in tags.split(',')]
    if q:
        for w in re.findall(r"[a-z']{4,}", q.lower()):
            if w not in tg and len(tg) < 14:
                tg.append(w)
    mom = [m.strip() for m in moms.split(',')]
    rl = [ROLE[c] for c in roles]
    if category == 'green_screen' and 'overlay' not in rl:
        rl.insert(0, 'overlay')
    if category == 'overlay':
        rl = ['overlay']
    rl = rl[:3]
    incoming = a.get('incoming') or '_Incoming' in a['path']
    cn = clean_from_path(a['path']) if incoming else None
    if notes == '-':
        notes = None
    if org == 'indian':
        freq = 'rare'
    else:
        freq = 'common'
    if rate == 'banned':
        freq = 'rare'
    vol = -3 if int(en) >= 5 else 0
    obj = dict(id=a['id'], description=desc, moments=mom, roles=rl, tags=tg, quote=q, mood=mood, energy=int(en),
               content_rating=rate, copyright_risk=CR[cr], placement=placement, key_mode=k, use_window=uw,
               volume_db=vol, frequency=freq, notes=notes, category=category, folder=FOLD[fld], clean_name=cn, origin=org)
    out.append(obj)

json.dump(out, open(cat + '/tags/zz_review_review_speech_2.json', 'w', encoding='utf8'), indent=1, ensure_ascii=False)

# validate
ids = [a['id'] for a in assets]
res = json.load(open(cat + '/tags/zz_review_review_speech_2.json', encoding='utf8'))
assert len(res) == len(ids) == 340, (len(res), len(ids))
assert [r['id'] for r in res] == ids
bad = []
folders = tax['folders']
for r in res:
    for m in r['moments']:
        if m not in tax['moments']: bad.append((r['id'], 'moment', m))
    for m in r['roles']:
        if m not in tax['roles']: bad.append((r['id'], 'role', m))
    if r['placement'] not in tax['placement']: bad.append((r['id'], 'placement'))
    if r['key_mode'] not in tax['key_modes']: bad.append((r['id'], 'key'))
    if r['content_rating'] not in tax['content_rating']: bad.append((r['id'], 'rating'))
    if r['copyright_risk'] not in tax['copyright_risk']: bad.append((r['id'], 'cr'))
    if r['category'] not in tax['categories']: bad.append((r['id'], 'cat'))
    if r['folder'] not in folders: bad.append((r['id'], 'folder'))
    if not (1 <= len(r['moments']) <= 5): bad.append((r['id'], 'nmom'))
    if not (1 <= len(r['roles']) <= 3): bad.append((r['id'], 'nroles'))
    if not 1 <= r['energy'] <= 5: bad.append((r['id'], 'energy'))
    if r['origin'] not in ('indian', 'english', 'anime', 'game', 'none', 'other'): bad.append((r['id'], 'origin'))
    if r['use_window'] and not (0 <= r['use_window'][0] < r['use_window'][1]): bad.append((r['id'], 'window'))
    f = r['folder']
    exp = {'Meme Videos': 'meme_video', 'Green Screen': 'green_screen', 'Overlays & VFX': 'overlay'}[f.split('/')[0]]
    if exp != r['category']: bad.append((r['id'], 'folder/cat'))
print('bad', bad)
print('count', len(res))
print('indian', sum(r['origin'] == 'indian' for r in res))
print('banned', sum(r['content_rating'] == 'banned' for r in res), 'explicit', sum(r['content_rating'] == 'explicit' for r in res))
long_nowin = [r['id'] for r, a in zip(res, assets) if a['duration_s'] > 6 and not r['use_window']]
print('long without window', long_nowin)

